import strawberry
from strawberry.file_uploads import Upload
from strawberry.types import Info

@strawberry.type
class TeamAvatarPayload:
    team_id: int
    avatar_url: str

@strawberry.type
class Mutation:
    @strawberry.mutation
    async def update_team_avatar(
        self,
        info: Info,
        team_id: int,
        avatar: Upload
    ) -> TeamAvatarPayload:
        current_user = info.context.get("user")
        if not current_user:
            raise Exception("Not authenticated")

        team_service = info.context["team_service"]
        is_member = await team_service.is_team_admin(team_id=team_id, user_id=current_user.id)
        if not is_member:
            raise Exception("Permission denied: You must be an administrator of this team")

        file_bytes = await avatar.read()
        uploader = info.context["avatar_uploader"]
        url = await uploader.upload_and_set_avatar(team_id=team_id, data=file_bytes)

        return TeamAvatarPayload(team_id=team_id, avatar_url=url)
